import{z as B,x as p,o as E,c as A,q as n,j as s,D as r,d as e,s as i,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"蜜罐","description":"","frontmatter":{"title":"蜜罐","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/honeypot.md","filePath":"cs/honeypot.md","lastUpdated":1791413859000}'),d={name:"cs/honeypot.md"};function h(D,a,m,c,f,u){const o=p("Mermaid");return E(),A("div",null,[a[2]||(a[2]=n('<h1 id="蜜罐" tabindex="-1">蜜罐 <a class="header-anchor" href="#蜜罐" aria-label="Permalink to &quot;蜜罐&quot;">​</a></h1><div class="epigraph"><p>蜜罐是故意可发现的假系统：连上它的流量默认高可疑。它换来情报与低误报，前提是隔离足够，不被当成跳板打进真网。</p><footer>—— 据 Spitzner, *Honeypots*；Lance Spitzner 对蜜网的实践陈述</footer></div><p>上一课<a href="/cs/ids-rules">规则</a>误报高。缺口是<strong>高置信触点</strong>：没人该访问的地址。本课讲隔离与情报用途，不把蜜罐当诱捕违法的操作手册。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规则对扫描噪声吵：互联网背景流量里<a href="/cs/port-scanning">端口扫描</a>与爆破恒定存在，规则要在其中挑真攻击，误报难压。蜜罐翻转前提：正常流量不该出现在这里，任何连接默认可疑，误报趋于零。低交互模拟服务（协议指纹、假文件系统），便宜量大但可被指纹识别；高交互真系统可观测完整攻击链。缺口是逃逸与污染：蜜罐被占则成跳板。</p><h3 id="法律与伦理" tabindex="-1">法律与伦理 <a class="header-anchor" href="#法律与伦理" aria-label="Permalink to &quot;法律与伦理&quot;">​</a></h3><p>观测要符合政策：监控告知范围、蜜罐日志里误触者的个人数据。本课不讨论诱捕执法。</p><p><span class="marginnote">Spitzner。禁止用蜜罐数据去报复。DDoS 下一课换可用性轴。现代变体是金丝雀令牌：假凭据、假 URL 埋进文档与配置，被读取即告警——把高置信触点缩到单个 token。</span></p><p><span class="marginnote">直觉类比：蜜罐像沙滩上唯一的红伞——正常游客不会去撑它，谁坐上去谁就可疑。IDS 规则是在人海里找小偷，蜜罐是把「只有小偷才会去的地方」圈出来，信号天然干净。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层交互按预算与风险：低交互铺面（全端口假服务），高交互收细节。隔离是硬约束：专用 VLAN 或网络命名空间（回 <a href="/cs/network-segmentation">分段</a>），出站默认丢弃——抓到的样本不许回连；DNS、NTP 也与生产分开，防止蜜罐与真网互认；无真实凭据、无生产数据。日志外送 <a href="/cs/siem-logging">SIEM</a>，本机日志默认不可信。误触来源要登记：内部扫描器与监控探测给蜜罐减噪。对照 IDS：蜜罐事件默认真，仍要防误触（扫描自己）。</p>',12)),(E(),s(l,null,{default:r(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAKE%5B%22%E5%81%87%E6%9C%8D%E5%8A%A1%22%5D%20--%3E%20HIT%5B%22%E8%BF%9E%E6%8E%A5%E5%8D%B3%E5%8F%AF%E7%96%91%22%5D%0A%20%20HIT%20--%3E%20LOG%5B%22%E5%A4%96%E9%80%81%E6%97%A5%E5%BF%97%22%5D%0A%20%20FAKE%20--%3E%20ISO%5B%22%E7%A6%81%E5%87%BA%E7%AB%99%E9%98%B2%E8%B7%B3%E6%9D%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("机制是概率不对称：真资产在地址空间占极小比例，随机扫到的几乎全是假资产，攻击者探测成本不变，防守者信号纯度陡升。产出两条线：情报（提取载荷、TTP 映射 "),t("a",{href:"/cs/mitre-attack"},"ATT&CK"),e("）与告警（进 "),t("a",{href:"/cs/incident-response"},"事件响应"),e(" 流程）。失败模式：低交互指纹被识别后反成灯塔——攻击者据此绕开真网或投喂假情报；告警一多又被当噪声。欺骗服务观测。不替代补丁。DDoS 下一课是可用性洪水，蜜罐帮不上容量。")],-1)),a[5]||(a[5]=t("p",null,"一次蜜罐事件从触发到产出：",-1)),(E(),s(l,null,{default:r(()=>[i(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E8%9C%9C%E7%BD%90%E4%B8%8A%E7%9A%84%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20A%5B%22%E9%BB%98%E8%AE%A4%E9%AB%98%E5%8F%AF%E7%96%91%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20A%20--%3E%20O%5B%22%E6%8F%90%E5%8F%96%E8%BD%BD%E8%8D%B7%E4%B8%8E%E6%94%BB%E5%87%BB%E6%89%8B%E6%B3%95%22%5D%0A%20%20A%20--%3E%20S%5B%22%E8%BF%9B%E5%85%A5%E4%BA%8B%E4%BB%B6%E5%93%8D%E5%BA%94%E6%B5%81%E7%A8%8B%22%5D%0A%20%20O%20--%3E%20I%5B%22%E6%B2%89%E6%B7%80%E4%B8%BA%20ATT%26CK%20%E6%83%85%E6%8A%A5%22%5D%0A%20%20S%20--%3E%20R%5B%22%E9%81%8F%E5%88%B6%E4%B8%8E%E5%A4%84%E7%BD%AE%22%5D%0A%20%20A%20-.-%3E%20F%5B%22%E9%A3%8E%E9%99%A9%3A%20%E8%A2%AB%E6%8C%87%E7%BA%B9%E8%AF%86%E5%88%AB%E5%8F%8D%E6%88%90%E7%81%AF%E5%A1%94%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：一个 /16 网段里真资产只占 1%，攻击者随机扫描时约 99% 的命中落在假资产上——他多扫一倍只是多暴露一倍；防守者这边每条告警的含金量却接近百分之百。「概率不对称」说的就是这个差距。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写高交互逃逸。换情报不换容量，预算仍要先给补丁与基线。DDoS 缓解下一课。</p><p><span class="marginnote">常见误区：把蜜罐当成「抓黑客」的执法工具，或替代补丁的银弹。它只产出情报与告警，不缩小可被攻击的漏洞面；隔离没做足时，被攻占的蜜罐反而是攻击者最好的跳板。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>规则吵；蜜罐触点默认可疑。</li><li>隔离与禁出站是前提。</li><li>换情报，不换容量。</li><li>下一课 DDoS 缓解。</li><li>出处：Spitzner, <em>Honeypots</em>。</li></ul>',6))])}const _=B(d,[["render",h]]);export{T as __pageData,_ as default};
